CREATE INDEX IF NOT EXISTS memberships_user_channel ON memberships(user_id,channel_id);

CREATE INDEX IF NOT EXISTS xmpp_remote_queued ON xmpp_remote_messages(subscription_id,status,seq);
UPDATE archipel_schema SET version=27

CREATE INDEX IF NOT EXISTS federation_pending_order ON federation_deliveries(id) WHERE status='pending';

CREATE INDEX IF NOT EXISTS federation_pending_recipient ON federation_deliveries(recipient,id) WHERE status='pending';

CREATE INDEX IF NOT EXISTS federation_pending_activity ON federation_deliveries(activity_id,id) WHERE status='pending';

CREATE INDEX IF NOT EXISTS federation_outgoing_owner ON federation_outgoing(user_id,purpose,channel_id,id);

CREATE INDEX IF NOT EXISTS federation_outgoing_channel ON federation_outgoing(channel_id,id);
UPDATE archipel_schema SET version=28

CREATE TABLE IF NOT EXISTS native_changes (
  seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payload TEXT COLLATE "C" NOT NULL
);
UPDATE archipel_schema SET version=29

ALTER TABLE federation_follows ADD COLUMN stream_start BIGINT;

ALTER TABLE federation_follows ADD COLUMN stream_capable BIGINT NOT NULL DEFAULT 0;

ALTER TABLE federation_subscriptions ADD COLUMN stream_start BIGINT;

CREATE TABLE federation_channel_state (
  channel_id TEXT COLLATE "C" PRIMARY KEY REFERENCES channels(id) ON DELETE CASCADE DEFERRABLE,
  tail BIGINT NOT NULL DEFAULT 0, floor BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE federation_channel_events (
  channel_id TEXT COLLATE "C" NOT NULL REFERENCES channels(id) ON DELETE CASCADE DEFERRABLE,
  seq BIGINT NOT NULL, activity_id TEXT COLLATE "C" NOT NULL REFERENCES federation_outgoing(id) DEFERRABLE,
  created_at BIGINT NOT NULL, PRIMARY KEY(channel_id,seq)
);

CREATE INDEX federation_channel_events_age ON federation_channel_events(created_at);

CREATE TABLE federation_channel_cursors (
  channel_id TEXT COLLATE "C" PRIMARY KEY REFERENCES channels(id) ON DELETE CASCADE DEFERRABLE,
  cursor BIGINT NOT NULL, error TEXT COLLATE "C", retry_at BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE federation_channel_peers (
  channel_id TEXT COLLATE "C" NOT NULL REFERENCES channels(id) ON DELETE CASCADE DEFERRABLE,
  origin TEXT COLLATE "C" NOT NULL, cursor BIGINT NOT NULL, updated_at BIGINT NOT NULL,
  PRIMARY KEY(channel_id,origin)
);
UPDATE archipel_schema SET version=30

CREATE INDEX federation_legacy_followers ON federation_follows(channel_id,actor)
  WHERE status='accepted' AND (stream_capable=0 OR stream_start IS NULL);

CREATE TABLE federation_instance_state (id BIGINT PRIMARY KEY, tail BIGINT NOT NULL DEFAULT 0, floor BIGINT NOT NULL DEFAULT 0);

INSERT INTO federation_instance_state(id) VALUES(1);

CREATE TABLE federation_instance_events (
  seq BIGINT PRIMARY KEY, channel_id TEXT COLLATE "C" NOT NULL,
  channel_seq BIGINT NOT NULL, activity_id TEXT COLLATE "C" NOT NULL REFERENCES federation_outgoing(id) DEFERRABLE,
  created_at BIGINT NOT NULL, public BIGINT NOT NULL DEFAULT 0, epoch BIGINT NOT NULL DEFAULT 1, frame TEXT COLLATE "C",
  UNIQUE(channel_id,channel_seq)
);

CREATE INDEX federation_instance_events_age ON federation_instance_events(created_at);

CREATE TABLE federation_channel_epochs (channel_id TEXT COLLATE "C" PRIMARY KEY REFERENCES channels(id) ON DELETE CASCADE DEFERRABLE, epoch BIGINT NOT NULL DEFAULT 1);

CREATE TABLE federation_channel_keys (
  channel_id TEXT COLLATE "C" NOT NULL, epoch BIGINT NOT NULL, secret TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY(channel_id,epoch)
);

CREATE TABLE federation_instance_cursors (origin TEXT COLLATE "C" PRIMARY KEY, cursor BIGINT NOT NULL DEFAULT 0, error TEXT COLLATE "C", retry_at BIGINT NOT NULL DEFAULT 0);

CREATE TABLE federation_instance_incoming (
  origin TEXT COLLATE "C" NOT NULL, seq BIGINT NOT NULL, channel_actor TEXT COLLATE "C" NOT NULL, channel_seq BIGINT NOT NULL,
  frame TEXT COLLATE "C" NOT NULL, state TEXT COLLATE "C" NOT NULL DEFAULT 'pending', error TEXT COLLATE "C", retry_at BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY(origin,seq)
);

CREATE INDEX federation_instance_pending ON federation_instance_incoming(state,retry_at,origin,seq);

CREATE TABLE federation_received_keys (channel_actor TEXT COLLATE "C" NOT NULL, epoch BIGINT NOT NULL, secret TEXT COLLATE "C" NOT NULL, PRIMARY KEY(channel_actor,epoch));

ALTER TABLE federation_follows ADD COLUMN key_epoch BIGINT;

ALTER TABLE federation_follows ADD COLUMN instance_start BIGINT;

ALTER TABLE federation_subscriptions ADD COLUMN instance_start BIGINT;

CREATE INDEX federation_instance_channel_pending ON federation_instance_incoming(channel_actor,state,channel_seq);

INSERT INTO federation_instance_events(seq,channel_id,channel_seq,activity_id,created_at,public,epoch)
  SELECT ROW_NUMBER() OVER(ORDER BY e.created_at,e.channel_id,e.seq),e.channel_id,e.seq,e.activity_id,e.created_at,
    CASE WHEN c.visibility='public' THEN 1 ELSE 0 END,1 FROM federation_channel_events e JOIN channels c ON c.id=e.channel_id;

UPDATE federation_instance_state SET tail=COALESCE((SELECT MAX(seq) FROM federation_instance_events),0);
UPDATE archipel_schema SET version=31
